var __pageData = JSON.parse("{\"title\":\"JavaScript 原型链：从属性查找理解对象、构造函数与 class\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"javascript/03-prototype-chain.md\",\"filePath\":\"javascript/03-prototype-chain.md\"}");
